const today = new Date();
const dayOfWeek = today.toLocaleDateString('en-US', { weekday: 'long' });
const dateStr = today.toLocaleDateString('en-US');

const contentMap = {
  'Monday': {
    type: 'AI Concept Explained',
    theme: 'Break down one fundamental AI concept that beginners often struggle with, using simple analogies',
    imagePrompt: 'educational diagram, AI concept illustration, beginner-friendly infographic, learning visual'
  },
  'Tuesday': {
    type: 'AI vs Human',
    theme: 'Compare how AI and humans approach the same task differently, in beginner-friendly terms',
    imagePrompt: 'human vs AI comparison, side-by-side illustration, educational comparison chart'
  },
  'Wednesday': {
    type: 'Poll',
    theme: 'Simple poll about AI basics, misconceptions, or beginner preferences to engage the community',
    imagePrompt: 'poll interface, quiz visual, interactive learning, beginner-friendly question format'
  },
  'Thursday': {
    type: 'AI Tool Spotlight',
    theme: 'Introduce one beginner-friendly AI tool with simple explanation of what it does and how to use it',
    imagePrompt: 'AI tool interface, software screenshot, beginner tutorial visual, easy-to-use app'
  },
  'Friday': {
    type: 'AI Myth Busting',
    theme: 'Debunk common AI myths or misconceptions that beginners often have about artificial intelligence',
    imagePrompt: 'myth vs reality, fact vs fiction, educational debunking visual, truth revelation'
  },
  'Saturday': {
    type: 'Real World AI',
    theme: 'Show examples of AI that beginners use every day without realizing it',
    imagePrompt: 'everyday AI examples, real-world applications, daily life technology, familiar AI tools'
  },
  'Sunday': {
    type: 'Weekly AI Tip',
    theme: 'One simple, actionable tip for AI beginners to try this week',
    imagePrompt: 'tip illustration, helpful advice visual, beginner guide, step-by-step tip'
  }
};

const todayContent = contentMap[dayOfWeek];

// n8n expects an ARRAY of objects, not a single object
return [
  {
    date: dateStr,
    dayOfWeek: dayOfWeek,
    postType: todayContent.type,
    contentTheme: todayContent.theme,
    imagePrompt: todayContent.imagePrompt
  }
];

// Handle different response formats from LLM Chain vs OpenAI
let content = '';

// Check if it's from LLM Chain (your current setup)
if ($input.first().json.response) {
  content = $input.first().json.response;
} 
// Fallback for OpenAI format (in case you switch back)
else if ($input.first().json.choices && $input.first().json.choices[0]) {
  content = $input.first().json.choices[0].message.content;
}
// Direct text response
else if (typeof $input.first().json === 'string') {
  content = $input.first().json;
}
// Last resort - stringify the whole response
else {
  content = JSON.stringify($input.first().json);
  console.log('Unexpected response format:', $input.first().json);
}

const charCount = content.length;

// Generate engagement goal based on post type
const postType = $node["Set Day Variables"].json["postType"];
const engagementGoals = {
  'Industry News Commentary': 'Comments: 50+, Likes: 200+, Shares: 25+',
  'How-to Tutorial': 'Saves: 100+, Comments: 30+, Shares: 40+',
  'Poll': 'Votes: 500+, Comments: 25+, Shares: 15+',
  'Latest AI Tools': 'Shares: 75+, Saves: 150+, Comments: 35+',
  'Audience Q&A': 'Comments: 100+, Likes: 150+, Saves: 80+',
  'Behind-the-scenes': 'Likes: 200+, Comments: 40+, Saves: 60+',
  'Weekly Recap': 'Saves: 200+, Shares: 50+, Comments: 45+'
};

// Extract topic from content (first 50 chars usually contain the main topic)
const firstLine = content.split('\n')[0];
const topic = firstLine.substring(0, 50).replace(/[^a-zA-Z0-9\s]/g, '') + '...';

return {
  postContent: content,
  characterCount: charCount,
  engagementGoal: engagementGoals[postType] || 'Engagement: 100+',
  topicTheme: topic
};

const response = $input.first().json;
let imageUrl = '';
let imageDescription = $node["Set Day Variables"].json["imagePrompt"];

// Handle Together AI response format
if (response.data && response.data[0] && response.data[0].url) {
  imageUrl = response.data[0].url;
} else if (response.choices && response.choices[0] && response.choices[0].image_url) {
  imageUrl = response.choices[0].image_url;
} else {
  // Fallback if image generation fails
  imageUrl = 'Image generation failed - manual upload needed';
  console.log('Image generation response:', JSON.stringify(response, null, 2));
}

return {
  imageUrl: imageUrl,
  imageDescription: imageDescription,
  imageGenerated: imageUrl !== 'Image generation failed - manual upload needed'
};

